  "government_grants.parquet", "Total Government Grants", "Sum of government grants/contributions RECEIVED by 501(c) orgs in the (Year, dim) cell. This is income received from government sources \u2014 NOT Schedule I grants paid out to governments.", "Form 990 Part VIII line 1e, via efile Phase 0 (source_xpath /Return/ReturnData/IRS990/GovernmentGrantsAmt; NODC F9_08_REV_CONTR_GOVT_GRANT).", "990 filers only (990-PF/990-EZ do not carry line 1e). Coverage 2021\u20132024 in e-file; this panel publishes 2021\u20132023 (2024 filings still arriving). Most filers report none, so many cells are NA.",
  # program_related_investments
  "program_related_investments.parquet", "Year",      "Tax year as reported on the 990-PF filing.",                                          "efile Phase 0 program_related_investments.tax_year.",                                               "",
  "program_related_investments.parquet", "Total Program-Related Investments", "Sum of private-foundation program-related investments (PRI) totals across orgs in the (Year, dim) cell.", "Form 990-PF Part IX-B aggregate total (renumbered Part VIII-B for TY2021+), via efile Phase 0 (source_xpath /Return/ReturnData/IRS990PF/SumOfProgramRelatedInvstGrp/TotalAmt; NODC PF_09_PROG_RLTD_INVEST_AMT_TOT).", "990-PF filers only. Coverage 2021\u20132024 in e-file; this panel publishes 2021\u20132023 (2024 filings still arriving). Most foundations report no PRI, so many cells are NA.",
  # daf
  "daf.parquet",               "Year",                "Tax year as reported on the Schedule D filing.",                                      "DAF e-file Schedule D, harmonized.",                                                                 "",
  "daf.parquet",               "Number of Nonprofits","BMF active-window count of orgs in the cell \u2014 denominator for the dashboard's 'Percentage of Nonprofits with DAFs' metric.", "Aggregate of BMF rows where org_year_first \u2264 Year \u2264 org_year_last.",                  "Matches the number_nonprofits panel for the same cells.",
  "daf.parquet",               "Number of DAFs",      "Sum of donor-advised funds (and 'other similar funds') reported end-of-year, across orgs in the cell.", "Form 990 Schedule D Part I Line 1: SD_01_TOT_NUM_EOY_DAF + SD_01_TOT_NUM_EOY_OTH.",        "DAF reporting began 2008; coverage in this dataset starts 2021 (earlier years not in e-file).",
  "daf.parquet",               "Total Contributions", "Sum of aggregate contributions to DAFs (and OSFs) for the cell.",                    "Schedule D Pt I Line 2: SD_01_AGGREGATE_CONTR_DAF + _OTH.",                                          "",
  "daf.parquet",               "Total Grants",        "Sum of aggregate grants made from DAFs (and OSFs).",                                 "Schedule D Pt I Line 3: SD_01_AGGREGATE_GRANT_DAF + _OTH.",                                          "",
  "daf.parquet",               "Total Value",         "Sum of aggregate end-of-year value of DAFs (and OSFs).",                             "Schedule D Pt I Line 4: SD_01_AGGREGATE_VALUE_EOY_DAF + _OTH.",                                      "",
  "daf.parquet",               "Has DAF",             "Count of orgs in the cell with at least one DAF (num_dafs > 0).",                    "Derived per-row from Number of DAFs > 0, summed.",                                                   "",
  # nested_geographies
  "nested_geographies.csv",    "Census State",        "2-letter USPS state code.",                                                          "BMF.",                                                                                               "",
