  "nested_geographies.csv",    "Census Region",       "US Census region.",                                                                  "Derived from state.",                                                                                "",
  # county_fips_crosswalk
  "county_fips_crosswalk.parquet", "Census State",    "2-letter USPS state code.",                                                          "nccs-data-bmf county FIPS crosswalk.",                                                               "",
